PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE availabilities (
	id INTEGER NOT NULL, 
	faculty_id VARCHAR(13) NOT NULL, 
	term VARCHAR(16) NOT NULL, 
	slot_code VARCHAR(12) NOT NULL, 
	state VARCHAR(16) NOT NULL, 
	effective_from DATE NOT NULL, 
	effective_to DATE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (faculty_id, term, slot_code), 
	CHECK (state IN ('available', 'unavailable', 'leave')), 
	CHECK (effective_to >= effective_from), 
	FOREIGN KEY(faculty_id) REFERENCES faculty (id)
);
CREATE TABLE courses (
	id VARCHAR(13) NOT NULL, 
	program_id VARCHAR(13) NOT NULL, 
	title VARCHAR(160) NOT NULL, 
	credits INTEGER NOT NULL, 
	course_type VARCHAR(16) NOT NULL, 
	demand_profile VARCHAR(16) NOT NULL, 
	lifecycle_state VARCHAR(16) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (credits BETWEEN 1 AND 6), 
	CHECK (course_type IN ('core', 'elective')), 
	CHECK (demand_profile IN ('popular', 'typical', 'low')), 
	CHECK (lifecycle_state IN ('active', 'inactive', 'retired')), 
	FOREIGN KEY(program_id) REFERENCES programs (id)
);
CREATE TABLE faculty (
	id VARCHAR(13) NOT NULL, 
	program_id VARCHAR(13) NOT NULL, 
	weekly_workload_limit INTEGER NOT NULL, 
	lifecycle_state VARCHAR(16) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (weekly_workload_limit BETWEEN 1 AND 40), 
	CHECK (lifecycle_state IN ('active', 'inactive', 'retired')), 
	FOREIGN KEY(program_id) REFERENCES programs (id)
);
CREATE TABLE faculty_skills (
	id INTEGER NOT NULL, 
	faculty_id VARCHAR(13) NOT NULL, 
	course_id VARCHAR(13) NOT NULL, 
	proficiency INTEGER NOT NULL, 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	PRIMARY KEY (id), 
	UNIQUE (faculty_id, course_id), 
	CHECK (proficiency BETWEEN 1 AND 5), 
	CHECK (effective_to IS NULL OR effective_to >= effective_from), 
	FOREIGN KEY(faculty_id) REFERENCES faculty (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE forecast_runs (
	id VARCHAR(20) NOT NULL, 
	target_term VARCHAR(16) NOT NULL, 
	window_terms VARCHAR(80) NOT NULL, 
	seed INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (status IN ('running', 'completed', 'failed'))
);
CREATE TABLE forecasts (
	id INTEGER NOT NULL, 
	run_id VARCHAR(20) NOT NULL, 
	course_id VARCHAR(13) NOT NULL, 
	historical_demand FLOAT NOT NULL, 
	current_interest INTEGER NOT NULL, 
	forecast_enrollment INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (run_id, course_id), 
	FOREIGN KEY(run_id) REFERENCES forecast_runs (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE ground_truth_cases (
	id VARCHAR(20) NOT NULL, 
	issue_type VARCHAR(48) NOT NULL, 
	entity_type VARCHAR(24) NOT NULL, 
	entity_id VARCHAR(24) NOT NULL, 
	related_entity_id VARCHAR(24) NOT NULL, 
	expected_decision VARCHAR(32) NOT NULL, 
	details VARCHAR(240) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (issue_type IN ('faculty_outside_skillset', 'workload_exceeded', 'section_capacity_too_low', 'prerequisite_order_violation', 'duplicate_section_assignment'))
);
CREATE TABLE prerequisites (
	id INTEGER NOT NULL, 
	course_id VARCHAR(13) NOT NULL, 
	prerequisite_course_id VARCHAR(13) NOT NULL, 
	min_grade VARCHAR(2) NOT NULL, 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	PRIMARY KEY (id), 
	UNIQUE (course_id, prerequisite_course_id), 
	CHECK (course_id != prerequisite_course_id), 
	CHECK (effective_to IS NULL OR effective_to >= effective_from), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(prerequisite_course_id) REFERENCES courses (id)
);
CREATE TABLE programs (
	id VARCHAR(13) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	department VARCHAR(80) NOT NULL, 
	lifecycle_state VARCHAR(16) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (lifecycle_state IN ('active', 'inactive', 'retired')), 
	UNIQUE (name)
);
CREATE TABLE registration_interests (
	id VARCHAR(16) NOT NULL, 
	student_plan_id VARCHAR(16) NOT NULL, 
	course_id VARCHAR(13) NOT NULL, 
	term VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (student_plan_id, course_id), 
	CHECK (status IN ('registered', 'waitlisted', 'interested', 'withdrawn')), 
	FOREIGN KEY(student_plan_id) REFERENCES student_plans (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE rooms (
	id VARCHAR(12) NOT NULL, 
	building VARCHAR(40) NOT NULL, 
	capacity INTEGER NOT NULL, 
	lifecycle_state VARCHAR(16) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (capacity BETWEEN 1 AND 500), 
	CHECK (lifecycle_state IN ('active', 'inactive', 'retired'))
);
CREATE TABLE sections (
	id VARCHAR(18) NOT NULL, 
	run_id VARCHAR(20) NOT NULL, 
	course_id VARCHAR(13) NOT NULL, 
	room_id VARCHAR(12) NOT NULL, 
	term VARCHAR(16) NOT NULL, 
	capacity INTEGER NOT NULL, 
	scheduled_at DATETIME NOT NULL, 
	slot_code VARCHAR(12) NOT NULL, 
	lifecycle_state VARCHAR(16) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (capacity > 0), 
	CHECK (lifecycle_state IN ('proposed', 'approved', 'cancelled')), 
	UNIQUE (room_id, scheduled_at), 
	FOREIGN KEY(run_id) REFERENCES forecast_runs (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(room_id) REFERENCES rooms (id)
);
CREATE TABLE state_events (
	id INTEGER NOT NULL, 
	run_id VARCHAR(20), 
	entity_type VARCHAR(32) NOT NULL, 
	entity_id VARCHAR(24) NOT NULL, 
	event_type VARCHAR(32) NOT NULL, 
	from_state VARCHAR(16), 
	to_state VARCHAR(16) NOT NULL, 
	occurred_at DATETIME NOT NULL, 
	details VARCHAR(240) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(run_id) REFERENCES forecast_runs (id)
);
CREATE TABLE student_plans (
	id VARCHAR(16) NOT NULL, 
	student_ref VARCHAR(16) NOT NULL, 
	program_id VARCHAR(13) NOT NULL, 
	term VARCHAR(16) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (student_ref, term), 
	FOREIGN KEY(program_id) REFERENCES programs (id)
);
CREATE TABLE unmet_demand (
	id INTEGER NOT NULL, 
	run_id VARCHAR(20) NOT NULL, 
	course_id VARCHAR(13) NOT NULL, 
	unmet_seats INTEGER NOT NULL, 
	reason VARCHAR(32) NOT NULL, 
	details VARCHAR(240) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (unmet_seats > 0), 
	FOREIGN KEY(run_id) REFERENCES forecast_runs (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE workload_assignments (
	id VARCHAR(18) NOT NULL, 
	section_id VARCHAR(18) NOT NULL, 
	faculty_id VARCHAR(13) NOT NULL, 
	weekly_hours INTEGER NOT NULL, 
	lifecycle_state VARCHAR(16) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (section_id), 
	CHECK (weekly_hours BETWEEN 1 AND 40), 
	CHECK (lifecycle_state IN ('proposed', 'approved', 'cancelled')), 
	FOREIGN KEY(section_id) REFERENCES sections (id), 
	FOREIGN KEY(faculty_id) REFERENCES faculty (id)
);
CREATE INDEX ix_availabilities_faculty_id ON availabilities (faculty_id);
CREATE INDEX ix_availabilities_term ON availabilities (term);
CREATE INDEX ix_availability_term_slot ON availabilities (term, slot_code);
CREATE INDEX ix_courses_program_id ON courses (program_id);
CREATE INDEX ix_faculty_program_id ON faculty (program_id);
CREATE INDEX ix_faculty_skills_course_id ON faculty_skills (course_id);
CREATE INDEX ix_faculty_skills_faculty_id ON faculty_skills (faculty_id);
CREATE INDEX ix_forecast_runs_target_term ON forecast_runs (target_term);
CREATE INDEX ix_forecasts_course_id ON forecasts (course_id);
CREATE INDEX ix_forecasts_run_id ON forecasts (run_id);
CREATE INDEX ix_interest_term_status ON registration_interests (term, status);
CREATE INDEX ix_prerequisites_course_id ON prerequisites (course_id);
CREATE INDEX ix_prerequisites_prerequisite_course_id ON prerequisites (prerequisite_course_id);
CREATE INDEX ix_registration_interests_course_id ON registration_interests (course_id);
CREATE INDEX ix_registration_interests_student_plan_id ON registration_interests (student_plan_id);
CREATE INDEX ix_registration_interests_term ON registration_interests (term);
CREATE INDEX ix_sections_course_id ON sections (course_id);
CREATE INDEX ix_sections_run_id ON sections (run_id);
CREATE INDEX ix_sections_term ON sections (term);
CREATE INDEX ix_state_events_entity_id ON state_events (entity_id);
CREATE INDEX ix_state_events_run_id ON state_events (run_id);
CREATE INDEX ix_student_plans_program_id ON student_plans (program_id);
CREATE INDEX ix_student_plans_term ON student_plans (term);
CREATE INDEX ix_unmet_demand_course_id ON unmet_demand (course_id);
CREATE INDEX ix_unmet_demand_run_id ON unmet_demand (run_id);
CREATE INDEX ix_workload_assignments_faculty_id ON workload_assignments (faculty_id);
CREATE INDEX ix_workload_assignments_section_id ON workload_assignments (section_id);
COMMIT;
PRAGMA foreign_keys=ON;
